// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address bankDeployer, address k) public {
        vm.assume(bankDeployer != address(0));

        vm.prank(bankDeployer);
        BankImpl bank = new BankImpl();

        vm.deal(address(bank), 1 ether);

        vm.prank(address(bank));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        uint bal = c.tokenBalance(address(bank));

        assertTrue(bal == 20);
    }
}

contract BankImpl {
    function supportsToken() external pure returns (bytes32){
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
